{
  "findings": [
    {
      "severity": "major",
      "where": "askFriend fetch catch",
      "claim": "The fetch error handler only checks the timeout signal, so a caller abort is misclassified and wrapped as a connectivity error.",
      "why": "If the user aborts while the initial fetch is pending, the promise rejects with a generic friends: cannot reach error instead of an abort error, which breaks the escape hatch and can confuse the agent's cancellation handling.",
      "test": "Abort the signal during a pending fetch to /chat/completions; expect askFriend to reject with an abort error, but the current code rejects with the cannot-reach message."
    },
    {
      "severity": "major",
      "where": "loadFriends/readKey and DEFAULTS",
      "claim": "The legacy single-friend config fallback does not fall back to the legacy API key file path.",
      "why": "Existing users migrating from the pre-rename config location have their config at ~/.config/pi-escalation/config.json and likely their key at ~/.config/pi-escalation/friend_key; the fallback reads the old config but the default key remains at ~/.config/pi-friends/friend_key, so readKey fails.",
      "test": "Create a legacy config and key under ~/.config/pi-escalation/ with no new config, then read the friend key; expect the legacy key content, but the current code reads the new key path."
    },
    {
      "severity": "major",
      "where": "SSE parsing loop in askFriend",
      "claim": "The SSE parser ignores error events and does not surface stream-level errors.",
      "why": "If the server sends a streaming error, the client accumulates no answer and returns an empty answer, causing the tool to report an empty answer instead of the actual server error.",
      "test": "Fake SSE server sends a final data event containing an error object; expect askFriend to reject with that error, but the current code resolves with an empty answer."
    }
  ],
  "needs": [
    "The exact error payload shape sent by the friend server for stream-level errors.",
    "The call-site handling of askFriend rejections to know how abort errors are consumed.",
    "The actual legacy API key file location and whether the legacy config ever contained a keyFile field."
  ]
}
